head.script:
scwin.gVar = {
    "cDisabled" : "",
    "cReadOnly" : "",
}



// 테스트 설명, 유효성 값 설정
//  - @spec 의 "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다." 는
//    브라우저 구현 차이에 대한 안내 문구로 확인 수단을 만들 수 없어 유효성에서 제외한다. (secret_E_onblur_1 선례)
//  - e 객체의 개별 속성(e.altKey, e.button, e.clientX 등)은 표준 DOM 이벤트 속성이라 개별 유효성으로 만들지 않는다.
//  - onmousedown, onfocus, onmouseup 은 발생 순서 확인용 출력으로만 사용한다.
scwin.tData = {
    "description" : "[secret > E > onclick]<br/>Secret 컴포넌트를 마우스 왼쪽 버튼으로 클릭할 때 발생합니다.",
    "validation" : [
        "Secret 컴포넌트를 마우스 왼쪽 버튼으로 클릭할 때 onclick 이벤트가 발생합니다.",
        "이벤트 핸들러에 PointerEvent 객체 e 가 전달됩니다.",
        "Secret 컴포넌트를 클릭하면 'onmousedown > onfocus > onmouseup > onclick' 순서로 이벤트가 발생합니다.",
        "disabled=true 인 경우 onclick 이벤트가 발생하지 않지만 readOnly=true 인 경우엔 onclick 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 코드값 1 = 미설정)
    con_disabled.setValue("1");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    scwin.gVar["cDisabled"] = con_disabled.getText();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        disabled : scwin.gVar["cDisabled"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onmousedown", "onfocus", "onmouseup", "onclick"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, eList);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 발생 순서 확인용 출력 - validation 3 판정 출력 (발생 즉시 한 줄 출력 = 출력 순서가 실제 발생 순서)
scwin.target1_onmousedown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onmousedown");
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onfocus");
}



scwin.target1_onmouseup = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onmouseup");
}



// 테스트 샘플의 이벤트 처리 (마우스 왼쪽 버튼 클릭) - validation 1, 2, 3, 4 판정 출력
scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onclick (disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " / readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
